import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Input, Alert, api } from '../App';

export default function MappingPage() {
  const [parties,   setParties]   = useState([]);
  const [gardens,   setGardens]   = useState([]);
  const [selected,  setSelected]  = useState(null);
  const [mapped,    setMapped]    = useState([]);
  const [search,    setSearch]    = useState('');
  const [gSearch,   setGSearch]   = useState('');
  const [saving,    setSaving]    = useState(false);
  const [alert,     setAlert]     = useState(null);
  const [newParty,  setNewParty]  = useState({ name:'', code:'', contact:'' });
  const [addMode,   setAddMode]   = useState(false);

  const load = useCallback(async () => {
    const [p, g] = await Promise.all([
      api.get('/mapping/summary/all'),
      api.get('/mapping/gardens')
    ]);
    setParties(p.data);
    setGardens(g.data);
  }, []);

  useEffect(() => { load(); }, [load]);

  const selectParty = async (p) => {
    setSelected(p);
    setAlert(null);
    const r = await api.get(`/mapping/${p.id}`);
    setMapped(r.data.map(x => x.garden));
  };

  const toggleGarden = (g) => {
    setMapped(m => m.includes(g) ? m.filter(x => x !== g) : [...m, g]);
  };

  const selectAll = (filtered) => {
    setMapped(m => {
      const existing = new Set(m);
      filtered.forEach(g => existing.add(g));
      return Array.from(existing);
    });
  };

  const clearAll = (filtered) => {
    const toRemove = new Set(filtered);
    setMapped(m => m.filter(g => !toRemove.has(g)));
  };

  const save = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      await api.post('/mapping', { party_id: selected.id, gardens: mapped });
      setAlert({ msg: `✅ Saved ${mapped.length} garden mappings for ${selected.party_name}`, type:'success' });
      load();
    } catch (e) {
      setAlert({ msg: '❌ ' + (e.response?.data?.error || e.message), type:'error' });
    } finally {
      setSaving(false);
    }
  };

  const addParty = async () => {
    if (!newParty.name || !newParty.code) { setAlert({ msg:'Party name and code required', type:'error'}); return; }
    try {
      await api.post('/parties', { party_name: newParty.name, party_code: newParty.code, contact: newParty.contact });
      setNewParty({ name:'', code:'', contact:'' });
      setAddMode(false);
      load();
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type:'error' });
    }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete party "${name}"? This removes all mappings.`)) return;
    await api.delete(`/parties/${id}`);
    setSelected(null);
    setMapped([]);
    load();
  };

  const filteredGardens = gardens.filter(g => g.toLowerCase().includes(gSearch.toLowerCase()));
  const filteredParties = parties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div>
      <h2 style={{ marginBottom:6, color:'#1a3c5e' }}>🔗 Party-Garden Mapping</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>
        Map each party to their gardens. One party can be mapped to multiple gardens (up to 100+).
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display:'flex', gap:16, alignItems:'flex-start' }}>
        {/* LEFT: Party list */}
        <Card style={{ width:280, minWidth:260, flexShrink:0 }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:12 }}>
            <h3 style={{ fontSize:15 }}>Parties ({filteredParties.length})</h3>
            <Button size="sm" onClick={() => setAddMode(!addMode)}>+ Add</Button>
          </div>

          {addMode && (
            <div style={{ background:'#f0f8ff', padding:12, borderRadius:6, marginBottom:12 }}>
              <Input label="Party Name" value={newParty.name} onChange={v => setNewParty(p => ({...p, name:v}))} placeholder="e.g. Gupta Tea Co." />
              <Input label="Party Code" value={newParty.code} onChange={v => setNewParty(p => ({...p, code:v}))} placeholder="e.g. GTC001" />
              <Input label="Contact"    value={newParty.contact} onChange={v => setNewParty(p => ({...p, contact:v}))} placeholder="Phone / email" />
              <div style={{ display:'flex', gap:8 }}>
                <Button size="sm" variant="success" onClick={addParty}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setAddMode(false)}>Cancel</Button>
              </div>
            </div>
          )}

          <input
            value={search} onChange={e => setSearch(e.target.value)}
            placeholder="Search parties…"
            style={{ width:'100%', padding:'6px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13, marginBottom:8 }}
          />

          <div style={{ maxHeight:500, overflowY:'auto' }}>
            {filteredParties.map(p => (
              <div
                key={p.id}
                onClick={() => selectParty(p)}
                style={{
                  padding:'8px 10px', borderRadius:6, cursor:'pointer', marginBottom:4,
                  background: selected?.id === p.id ? '#dbeafe' : '#f9fafb',
                  border: selected?.id === p.id ? '1.5px solid #93c5fd' : '1.5px solid transparent',
                  display:'flex', justifyContent:'space-between', alignItems:'flex-start'
                }}
              >
                <div>
                  <div style={{ fontWeight:600, fontSize:13, color:'#1a2533' }}>{p.party_name}</div>
                  <div style={{ fontSize:11, color:'#888' }}>{p.party_code} · {p.garden_count} gardens</div>
                </div>
                <button
                  onClick={e => { e.stopPropagation(); delParty(p.id, p.party_name); }}
                  style={{ background:'none', border:'none', cursor:'pointer', color:'#ccc', fontSize:14, padding:'0 2px' }}
                  title="Delete party"
                >✕</button>
              </div>
            ))}
            {filteredParties.length === 0 && <div style={{ color:'#aaa', fontSize:13, padding:12, textAlign:'center' }}>No parties found</div>}
          </div>
        </Card>

        {/* RIGHT: Garden selection */}
        <div style={{ flex:1 }}>
          {!selected ? (
            <Card style={{ textAlign:'center', padding:40, color:'#aaa' }}>
              Select a party from the left to manage their garden mappings
            </Card>
          ) : (
            <Card>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
                <div>
                  <h3 style={{ fontSize:16 }}>{selected.party_name}</h3>
                  <div style={{ fontSize:12, color:'#888' }}>{selected.party_code} · {mapped.length} gardens selected</div>
                </div>
                <div style={{ display:'flex', gap:8 }}>
                  <Button size="sm" variant="outline" onClick={() => selectAll(filteredGardens)}>Select All Shown</Button>
                  <Button size="sm" variant="outline" onClick={() => clearAll(filteredGardens)}>Clear Shown</Button>
                  <Button size="sm" variant="success" onClick={save} disabled={saving}>
                    {saving ? 'Saving…' : `💾 Save (${mapped.length})`}
                  </Button>
                </div>
              </div>

              <input
                value={gSearch} onChange={e => setGSearch(e.target.value)}
                placeholder="Search gardens…"
                style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13, marginBottom:12 }}
              />

              <div style={{ display:'flex', gap:8, flexWrap:'wrap', maxHeight:440, overflowY:'auto' }}>
                {filteredGardens.map(g => {
                  const isMapped = mapped.includes(g);
                  return (
                    <div
                      key={g}
                      onClick={() => toggleGarden(g)}
                      style={{
                        padding:'5px 12px', borderRadius:20, cursor:'pointer', fontSize:12, fontWeight:600,
                        border: `1.5px solid ${isMapped ? '#1a7a4a' : '#e2e8f0'}`,
                        background: isMapped ? '#dcfce7' : '#f9fafb',
                        color: isMapped ? '#166534' : '#555',
                        userSelect:'none', transition:'all 0.1s'
                      }}
                    >
                      {isMapped ? '✓ ' : ''}{g}
                    </div>
                  );
                })}
                {filteredGardens.length === 0 && (
                  <div style={{ color:'#aaa', fontSize:13, padding:12 }}>No gardens found. Import a Catalogue first.</div>
                )}
              </div>

              {mapped.length > 0 && (
                <div style={{ marginTop:14, padding:10, background:'#f0f8ff', borderRadius:6 }}>
                  <div style={{ fontSize:12, fontWeight:600, color:'#1a3c5e', marginBottom:6 }}>Mapped gardens ({mapped.length}):</div>
                  <div style={{ fontSize:12, color:'#555', lineHeight:1.8 }}>{mapped.sort().join(' · ')}</div>
                </div>
              )}
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}
